package npc

import chisel3._
import chisel3.util._
import MundusConfig._
import MundusParams._

// The AGU performs no register-address comparisons.  Its one-hot control is
// generated by isu_agu_ctrl's registered early-compare network.
class isu_agu extends Module {
  val io = IO(new Bundle {
    val agu_fwd_sel_iss = Input(UInt(AGU_FWD_SEL_WIDTH.W))

    val gpr_rs1_val  = Input(UInt(REG_DATA_WIDTH.W))
    val ex1_reg_val_q = Input(UInt(REG_DATA_WIDTH.W))
    val ex2_reg_val_q = Input(UInt(REG_DATA_WIDTH.W))
    val ex3_reg_val_q = Input(UInt(REG_DATA_WIDTH.W))
    val ex4_reg_val_q = Input(UInt(REG_DATA_WIDTH.W))

    val base = Output(UInt(REG_DATA_WIDTH.W))
  })

  io.base := 
    Fill(32, io.agu_fwd_sel_iss(4)) & io.ex1_reg_val_q |   // ex2_in
    Fill(32, io.agu_fwd_sel_iss(3)) & io.ex2_reg_val_q |   // ex3_in
    Fill(32, io.agu_fwd_sel_iss(2)) & io.ex3_reg_val_q |   // ex4_in
    Fill(32, io.agu_fwd_sel_iss(1)) & io.ex4_reg_val_q |   // wbu_in
    Fill(32, io.agu_fwd_sel_iss(0)) & io.gpr_rs1_val
}
